+    @Override
+    String afterTotal(Reservation reservation) {
+        BigDecimal iss = PriceCalculator.cents(reservation.price().total().multiply(ISS_RATE));
+        return "ISS retido (5%): " + wording().money().apply(iss) + "\n";
+    }
+}
