52:    /**
53:     * A kind is given when any of its fields is filled. If it is given but some field is missing, it is incomplete
54:     * and the request is rejected.
55:     */
56:    private static boolean given(String... values) {
57:        int filled = 0;
58:        for (String value : values) {
59:            if (value != null && !value.isBlank()) {
60:                filled++;
61:            }
62:        }
63:        if (filled > 0 && filled < values.length) {
64:            throw new HotelException(ErrorCode.INVALID_REQUEST, "the identification of the guest is incomplete");
65:        }
66:        return filled > 0;
67:    }
